// ===== ROUTER INTELIGENTE COM CACHE E RATE LIMITING v2.0 =====

const items = [];

// Cache global simples (em produção usar Redis)
if (typeof global.firewallCache === 'undefined') {
  global.firewallCache = {
    classifications: new Map(),
    rateLimits: new Map(),
    recentMessages: new Set()
  };
}

// Configurações
const CONFIG = {
  RATE_LIMIT_PER_HOUR: 10,
  CACHE_TTL_HOURS: 24,
  DEDUP_WINDOW_MINUTES: 5
};

// Função para criar hash simples
function createHash(text) {
  let hash = 0;
  for (let i = 0; i < text.length; i++) {
    const char = text.charCodeAt(i);
    hash = ((hash << 5) - hash) + char;
    hash = hash & hash;
  }
  return Math.abs(hash).toString(16).substring(0, 12);
}

// Normalização de texto avançada
function normalizeText(text) {
  return text
    .toLowerCase()
    // Decode URL encoding
    .replace(/%[0-9a-f]{2}/gi, (match) => {
      try {
        return String.fromCharCode(parseInt(match.slice(1), 16));
      } catch {
        return match;
      }
    })
    // Normalize Unicode
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    // Caracteres similares
    .replace(/[1l|íìîï]/g, 'i')
    .replace(/[0oóòôõö]/g, 'o')
    .replace(/[5s$]/g, 's')
    .replace(/[éèêë]/g, 'e')
    .replace(/[áàâãä]/g, 'a')
    .replace(/[úùûü]/g, 'u')
    .replace(/ç/g, 'c')
    // Remove pontuação extra
    .replace(/[^\w\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

// Rate limiting
function checkRateLimit(sender) {
  const now = Date.now();
  const hourAgo = now - (60 * 60 * 1000);
  const senderHash = createHash(sender);

  if (!global.firewallCache.rateLimits.has(senderHash)) {
    global.firewallCache.rateLimits.set(senderHash, []);
  }

  const timestamps = global.firewallCache.rateLimits.get(senderHash);
  const recentTimestamps = timestamps.filter(ts => ts > hourAgo);
  global.firewallCache.rateLimits.set(senderHash, recentTimestamps);

  if (recentTimestamps.length >= CONFIG.RATE_LIMIT_PER_HOUR) {
    return { allowed: false, count: recentTimestamps.length };
  }

  recentTimestamps.push(now);
  global.firewallCache.rateLimits.set(senderHash, recentTimestamps);
  return { allowed: true, count: recentTimestamps.length };
}

// Verificação de duplicação
function checkDuplication(messageHash) {
  const now = Date.now();
  const windowAgo = now - (CONFIG.DEDUP_WINDOW_MINUTES * 60 * 1000);

  // Limpa entradas antigas
  const oldEntries = Array.from(global.firewallCache.recentMessages)
    .filter(entry => {
      const [hash, timestamp] = entry.split('|');
      return parseInt(timestamp) < windowAgo;
    });

  oldEntries.forEach(entry => {
    global.firewallCache.recentMessages.delete(entry);
  });

  const entry = `${messageHash}|${now}`;

  if (Array.from(global.firewallCache.recentMessages).some(e => e.startsWith(messageHash + '|'))) {
    return { isDuplicate: true };
  }

  global.firewallCache.recentMessages.add(entry);
  return { isDuplicate: false };
}

// Processamento principal
for (const item of $input.all()) {
  const startTime = Date.now();

  // Unifica eventos de diferentes canais
  let unifiedEvent = {
    channel: '',
    from: '',
    input_text: '',
    raw: item.json,
    timestamp: new Date().toISOString(),
    router_version: '2.0'
  };

  // Detecta o canal baseado na origem
  if (item.json.snippet || item.json.subject) {
    // Gmail
    unifiedEvent.channel = 'gmail';
    unifiedEvent.from = item.json.from || item.json.sender || 'unknown';
    unifiedEvent.input_text = item.json.snippet || item.json.bodyPlainText || item.json.subject || '';
  } else if (item.json.data || item.json.message) {
    // WhatsApp via EvolutionAPI
    unifiedEvent.channel = 'whatsapp';
    unifiedEvent.from = item.json.data?.key?.remoteJid || item.json.from || 'unknown';

    if (item.json.data?.message?.conversation) {
      unifiedEvent.input_text = item.json.data.message.conversation;
    } else if (item.json.data?.message?.extendedTextMessage?.text) {
      unifiedEvent.input_text = item.json.data.message.extendedTextMessage.text;
    } else if (item.json.message?.text) {
      unifiedEvent.input_text = item.json.message.text;
    } else {
      if (item.json.data?.message?.audioMessage) {
        unifiedEvent.input_text = '[AUDIO_MESSAGE_RECEIVED]';
      } else if (item.json.data?.message?.imageMessage) {
        unifiedEvent.input_text = '[IMAGE_MESSAGE_RECEIVED]';
      } else {
        unifiedEvent.input_text = '[UNKNOWN_MESSAGE_TYPE]';
      }
    }
  }

  // Normalização
  unifiedEvent.input_text = unifiedEvent.input_text.trim();

  // Validações básicas
  if (unifiedEvent.input_text.length < 3) {
    items.push({
      json: {
        ...unifiedEvent,
        router_decision: 'reject_too_short',
        safe_response: 'Mensagem muito curta.',
        processing_time_ms: Date.now() - startTime
      }
    });
    continue;
  }

  if (unifiedEvent.input_text.length > 4000) {
    items.push({
      json: {
        ...unifiedEvent,
        router_decision: 'reject_too_long', 
        safe_response: 'Mensagem muito longa. Divida em mensagens menores.',
        processing_time_ms: Date.now() - startTime
      }
    });
    continue;
  }

  // Rate limiting
  const rateLimitCheck = checkRateLimit(unifiedEvent.from);
  if (!rateLimitCheck.allowed) {
    items.push({
      json: {
        ...unifiedEvent,
        router_decision: 'rate_limited',
        safe_response: 'Limite de mensagens excedido. Tente novamente em 1 hora.',
        processing_time_ms: Date.now() - startTime
      }
    });
    continue;
  }

  // Verificação de duplicação
  const messageHash = createHash(unifiedEvent.input_text);
  const dupCheck = checkDuplication(messageHash);
  if (dupCheck.isDuplicate) {
    items.push({
      json: {
        ...unifiedEvent,
        router_decision: 'duplicate',
        safe_response: 'Mensagem duplicada detectada.',
        processing_time_ms: Date.now() - startTime
      }
    });
    continue;
  }

  // Verifica cache de classificações
  const normalized = normalizeText(unifiedEvent.input_text);
  const cacheKey = createHash(normalized);
  const cachedResult = global.firewallCache.classifications.get(cacheKey);

  if (cachedResult && (Date.now() - cachedResult.timestamp) < (CONFIG.CACHE_TTL_HOURS * 60 * 60 * 1000)) {
    items.push({
      json: {
        ...unifiedEvent,
        router_decision: 'cache_hit',
        cached_classification: cachedResult.classification,
        message_hash: messageHash,
        processing_time_ms: Date.now() - startTime
      }
    });
    continue;
  }

  // Aprovado para processamento
  items.push({
    json: {
      ...unifiedEvent,
      router_decision: 'process',
      message_hash: messageHash,
      normalized_text: normalized,
      rate_limit_count: rateLimitCheck.count,
      processing_time_ms: Date.now() - startTime
    }
  });
}

return items;

