// ===== REGRAS DE SEGURANÇA AVANÇADAS v2.0 =====

const items = [];

// Normalização para detecção
function normalizeForDetection(text) {
  return text
    .toLowerCase()
    // Decode URL encoding
    .replace(/%[0-9a-f]{2}/gi, (match) => {
      try {
        return String.fromCharCode(parseInt(match.slice(1), 16));
      } catch {
        return match;
      }
    })
    // Normalize caracteres
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[1l|íìîï]/g, 'i')
    .replace(/[0oóòôõö]/g, 'o') 
    .replace(/[5s$]/g, 's')
    .replace(/[éèêë]/g, 'e')
    .replace(/[áàâãä]/g, 'a')
    .replace(/[úùûü]/g, 'u')
    .replace(/ç/g, 'c')
    .replace(/[\W_]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

// Detecção de padrões fragmentados
function detectFragmentedPatterns(text) {
  const normalized = normalizeForDetection(text);
  const words = normalized.split(/\s+/);

  // Testa combinações de 2 a 4 palavras
  for (let len = 2; len <= Math.min(4, words.length); len++) {
    for (let i = 0; i <= words.length - len; i++) {
      const combination = words.slice(i, i + len).join('');
      if (isProhibitedPattern(combination)) {
        return {
          detected: true,
          pattern: combination,
          fragments: words.slice(i, i + len)
        };
      }
    }
  }

  return { detected: false };
}

// Padrões proibidos
function isProhibitedPattern(text) {
  const patterns = [
    // Prompt injection básico
    /ignore.*(?:tudo|acima|anterior|above|previous|instruction)/i,
    /esqueca.*(?:tudo|anterior|everything|previous)/i, 
    /desconsidera.*(?:acima|anterior|regra|sistema)/i,
    /revel[ae].*(?:prompt|instrucao|sistema|internal|system)/i,
    /mostr[ae].*(?:prompt|sistema|configuracao|internal)/i,
    /bypass.*(?:seguranca|filtro|safety|filter|security)/i,
    /contorn[ae].*(?:regra|filtro|politica|rule|policy)/i,
    /(?:override|substitui).*(?:anterior|previous|system)/i,
    /(?:modo|mode).*(?:desenvolvedor|developer|admin|debug)/i,
    /(?:finja|pretend|aja|act).*(?:como|as|que|if)/i,
    /jailbreak/i,
    /cole.*(?:pdf|arquivo|paste.*pdf)/i,
    /(?:dump|export[ae]|extraia).*(?:dados|config|data)/i,

    // Context switching
    /agora.*(?:esqueca|ignore|forget)/i,
    /nova.*(?:instrucao|regra|instruction|rule)/i,
    /a.*partir.*(?:agora|now)/i,

    // Ataques indiretos
    /como.*(?:pesquisador|researcher).*(?:faria|would)/i,
    /se.*(?:fosse|voce|you).*(?:desenvolvedor|developer)/i,
    /imagine.*(?:que|if).*(?:nao|no).*(?:limitacao|restriction)/i,

    // Adversarial
    /traduza.*(?:ignore|disregard|bypass)/i,
    /em.*(?:codigo|code).*(?:ignore|bypass)/i,
    /responda.*(?:sem|without).*(?:filtro|restriction)/i
  ];

  return patterns.some(pattern => pattern.test(text));
}

// Detecção de segredos
function detectSecrets(text) {
  const patterns = [
    /(api[_-]?key|apikey)\s*[:=]\s*[A-Za-z0-9._\-=+/]{12,}/gi,
    /(secret|password|pwd|senha)\s*[:=]\s*[A-Za-z0-9._\-=+/]{8,}/gi,
    /(token|bearer)\s*[:=]\s*[A-Za-z0-9._\-=+/]{20,}/gi,
    /(authorization|auth)\s*[:=]\s*[A-Za-z0-9._\-=+/]{15,}/gi,
    /sk-[A-Za-z0-9]{48}/g,
    /ghp_[A-Za-z0-9]{36}/g
  ];

  return patterns.some(pattern => pattern.test(text));
}

// Detecção de PII
function detectPII(text) {
  const patterns = [
    /\b\d{3}\.?\d{3}\.?\d{3}-?\d{2}\b/g, // CPF
    /\b\d{2}\.?\d{3}\.?\d{3}\/?\d{4}-?\d{2}\b/g, // CNPJ
    /\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b/g, // Email
    /(?:\+55\s?)?(?:\(?\d{2}\)?\s?)?\d{4,5}[-\s]?\d{4}/g // Telefone BR
  ];

  return patterns.some(pattern => pattern.test(text));
}

// Detecção de URLs suspeitas
function detectSuspiciousUrls(text) {
  const patterns = [
    /https?:\/\/[^\s]+\.(exe|bat|cmd|scr|zip|rar|apk|dmg)/gi,
    /https?:\/\/[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}/gi
  ];

  return patterns.some(pattern => pattern.test(text));
}

// Processamento principal
for (const item of $input.all()) {
  const startTime = Date.now();

  // Pula itens rejeitados pelo router
  if (item.json.router_decision !== 'process') {
    items.push({ json: item.json });
    continue;
  }

  const inputText = item.json.input_text;
  const normalized = item.json.normalized_text || normalizeForDetection(inputText);

  // Executa detecções
  const detections = {
    directPattern: isProhibitedPattern(normalized),
    fragmentedPattern: detectFragmentedPatterns(inputText),
    hasSecrets: detectSecrets(inputText),
    hasPII: detectPII(inputText),
    hasSuspiciousUrls: detectSuspiciousUrls(inputText)
  };

  // Calcula score de risco
  let riskScore = 0;

  if (detections.directPattern) riskScore += 0.4;
  if (detections.fragmentedPattern.detected) riskScore += 0.3;
  if (detections.hasSecrets) riskScore += 0.35;
  if (detections.hasPII) riskScore += 0.25;
  if (detections.hasSuspiciousUrls) riskScore += 0.3;

  riskScore = Math.min(riskScore, 1.0);

  // Determina nível de risco
  let riskLevel = 'low';
  if (riskScore >= 0.8) riskLevel = 'high';
  else if (riskScore >= 0.4) riskLevel = 'medium';

  // Cria flags compatíveis
  const staticFlags = {
    hasForbiddenPhrase: detections.directPattern || detections.fragmentedPattern.detected,
    hasSecret: detections.hasSecrets,
    hasCPF: /\b\d{3}\.?\d{3}\.?\d{3}-?\d{2}\b/.test(inputText),
    hasCNPJ: /\b\d{2}\.?\d{3}\.?\d{3}\/?\d{4}-?\d{2}\b/.test(inputText),
    hasEmail: /\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b/.test(inputText),
    hasPhone: /(?:\+55\s?)?(?:\(?\d{2}\)?\s?)?\d{4,5}[-\s]?\d{4}/.test(inputText),
    hasSuspiciousUrl: detections.hasSuspiciousUrls,
    staticRisk: riskLevel,
    riskScore: riskScore,
    detectionDetails: detections
  };

  items.push({
    json: {
      ...item.json,
      staticFlags,
      static_analysis_time_ms: Date.now() - startTime
    }
  });
}

return items;

