// Processador Allow com cache
const items = [];

for (const item of $input.all()) {
  const processedItem = {
    ...item.json,
    decision: 'allow',
    was_sanitized: false,
    processing_timestamp: new Date().toISOString(),
    security_level: 'normal'
  };

  // Atualiza cache se disponível
  if (typeof global.firewallCache !== 'undefined' && item.json.message_hash) {
    const cacheKey = item.json.message_hash;
    global.firewallCache.classifications.set(cacheKey, {
      classification: { classe: 'normal', confianca: 0.9 },
      decision: 'allow',
      timestamp: Date.now()
    });
  }

  items.push({ json: processedItem });
}

return items;

// Sanitizador avançado v2.0
const items = [];

for (const item of $input.all()) {
  const originalText = item.json.input_text;

  // Padrões para remoção
  let sanitizedText = originalText
    // Prompt injection
    .replace(/ignore\s+(tudo\s+acima|previous|all\s+above)/gi, '[INSTRUÇÃO_REDIRECIONADA]')
    .replace(/revel[ae]\s+(prompt|instruções|sistema)/gi, '[SOLICITAÇÃO_RESTRITA]')
    .replace(/bypass\s+(segurança|filtro|safety)/gi, '[TENTATIVA_BYPASS_REMOVIDA]')
    .replace(/modo\s+(desenvolvedor|developer|admin)/gi, '[MODO_ESPECIAL_REMOVIDO]')
    .replace(/(?:finja|pretend)\s+(?:que|that)/gi, '[ROLEPLAY_REMOVIDO]')

    // PII
    .replace(/\b\d{3}\.?\d{3}\.?\d{3}-?\d{2}\b/g, '[CPF_REMOVIDO]')
    .replace(/\b\d{2}\.?\d{3}\.?\d{3}\/?\d{4}-?\d{2}\b/g, '[CNPJ_REMOVIDO]')
    .replace(/\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b/g, '[EMAIL_REMOVIDO]')
    .replace(/(?:\+55\s?)?(?:\(?\d{2}\)?\s?)?\d{4,5}[-\s]?\d{4}/g, '[TELEFONE_REMOVIDO]')

    // Credenciais
    .replace(/(api[_-]?key|secret|token|password)\s*[:=]\s*[A-Za-z0-9._\-=+/]{8,}/gi, '[CREDENCIAL_REMOVIDA]')

    // URLs suspeitas
    .replace(/https?:\/\/[^\s]+\.(exe|bat|cmd|scr|zip|rar)/gi, '[URL_SUSPEITA_REMOVIDA]')
    .trim();

  // Se ficou muito vazio, cria pergunta contextual
  if (sanitizedText.length < originalText.length * 0.3 || sanitizedText.length < 15) {
    sanitizedText = 'Posso ajudá-lo com informações gerais. Que tipo de informação você precisa?';
  }

  const processedItem = {
    ...item.json,
    input_text: sanitizedText,
    original_text: originalText,
    decision: 'sanitize',
    was_sanitized: true,
    processing_timestamp: new Date().toISOString(),
    security_level: 'sanitized',
    sanitization_applied: true
  };

  // Atualiza cache
  if (typeof global.firewallCache !== 'undefined' && item.json.message_hash) {
    const cacheKey = item.json.message_hash;
    global.firewallCache.classifications.set(cacheKey, {
      classification: { classe: 'ambiguo', confianca: 0.7 },
      decision: 'sanitize',
      timestamp: Date.now()
    });
  }

  items.push({ json: processedItem });
}

return items;

// Processador Deny inteligente
const items = [];

function generateDenyResponse(classification) {
  const responses = {
    'override': 'Não posso atender a pedidos que tentem modificar meu funcionamento. Como posso ajudá-lo de forma construtiva?',
    'exfiltracao': 'Não posso compartilhar informações internas. Posso ajudar com informações gerais sobre o assunto?',
    'dados_sensiveis': 'Detectei informações pessoais na mensagem. Como posso ajudar de forma segura?',
    'ilegal': 'Não posso auxiliar com este tipo de conteúdo. Como posso ajudá-lo de forma positiva?'
  };

  return responses[classification] || 'Não posso atender a este pedido devido a políticas de segurança. Como posso ajudá-lo de forma apropriada?';
}

for (const item of $input.all()) {
  let classification = 'unknown';

  try {
    const parsed = JSON.parse(item.json.text || '{}');
    classification = parsed.classe || 'unknown';
  } catch (error) {
    // Fallback se não conseguir parsear
  }

  const processedItem = {
    ...item.json,
    decision: 'deny',
    was_sanitized: false,
    processing_timestamp: new Date().toISOString(),
    security_level: 'blocked',
    safe_response: generateDenyResponse(classification),
    deny_reason: `Classificado como '${classification}' com alta confiança`
  };

  // Atualiza cache
  if (typeof global.firewallCache !== 'undefined' && item.json.message_hash) {
    const cacheKey = item.json.message_hash;
    global.firewallCache.classifications.set(cacheKey, {
      classification: { classe: classification, confianca: 0.9 },
      decision: 'deny',
      timestamp: Date.now()
    });
  }

  items.push({ json: processedItem });
}

return items;

