// Guardrail de saída avançado
const items = [];

// Padrões de vazamento
const LEAK_PATTERNS = {
  prompt_leak: [
    /você é um.{0,50}(assistente|classificador)/gi,
    /suas diretrizes/gi,
    /nunca revele/gi,
    /não compartilhe/gi,
    /agosto de 2025/gi
  ],
  internal_info: [
    /n8n.{0,20}(workflow|node)/gi,
    /function.*return.*items/gi,
    /\$json\./gi,
    /typeVersion/gi
  ],
  sensitive_data: [
    /\b\d{3}\.?\d{3}\.?\d{3}-?\d{2}\b/g,
    /\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b/g,
    /(api[_-]?key|secret|token)\s*[:=]\s*[A-Za-z0-9._\-=+/]{8,}/gi
  ]
};

function analyzeResponse(response) {
  let riskScore = 0;
  const detectedLeaks = [];

  Object.entries(LEAK_PATTERNS).forEach(([category, patterns]) => {
    patterns.forEach(pattern => {
      if (pattern.test(response)) {
        riskScore += 0.3;
        detectedLeaks.push(category);
      }
    });
  });

  return {
    is_safe: riskScore < 0.3,
    risk_score: Math.min(riskScore, 1.0),
    detected_leaks: [...new Set(detectedLeaks)]
  };
}

function generateSafeAlternative() {
  return 'Não posso compartilhar esse tipo de informação. Como posso ajudá-lo de forma apropriada?';
}

for (const item of $input.all()) {
  let response = '';
  let isFromDeny = false;

  if (item.json.decision === 'deny') {
    response = item.json.safe_response || '';
    isFromDeny = true;
  } else {
    response = item.json.response || item.json.text || '';
  }

  let finalResponse = response;
  let wasBlocked = false;
  let blockReason = '';

  if (!isFromDeny && response) {
    const analysis = analyzeResponse(response);

    if (!analysis.is_safe) {
      wasBlocked = true;
      blockReason = `Vazamento detectado: ${analysis.detected_leaks.join(', ')}`;
      finalResponse = generateSafeAlternative();
    }
  }

  items.push({
    json: {
      ...item.json,
      original_response: response,
      safe_response: finalResponse,
      is_blocked: wasBlocked,
      block_reason: blockReason,
      final_check_timestamp: new Date().toISOString()
    }
  });
}

return items;

