// Logger avançado v2.0
const items = [];

function createHash(text) {
  if (!text) return null;
  let hash = 0;
  for (let i = 0; i < text.length; i++) {
    const char = text.charCodeAt(i);
    hash = ((hash << 5) - hash) + char;
    hash = hash & hash;
  }
  return Math.abs(hash).toString(16).substring(0, 12);
}

for (const item of $input.all()) {
  let llmClassification = null;

  try {
    if (item.json.response || item.json.text) {
      const content = (item.json.response || item.json.text).trim();
      const jsonMatch = content.match(/\{[^}]+\}/);
      if (jsonMatch) {
        llmClassification = JSON.parse(jsonMatch[0]);
      }
    }
  } catch (error) {
    llmClassification = { 
      classe: 'parse_error', 
      confianca: 0,
      error: error.message
    };
  }

  const logEntry = {
    timestamp: new Date().toISOString(),
    version: '2.0',
    execution_id: $executionId || 'unknown',

    // Dados anonimizados
    channel: item.json.channel,
    sender_hash: createHash(item.json.from),
    input_hash: createHash(item.json.input_text),
    output_hash: createHash(item.json.safe_response),

    // Métricas
    input_length: item.json.input_text?.length || 0,
    output_length: item.json.safe_response?.length || 0,
    processing_time_ms: item.json.processing_time_ms || 0,

    // Segurança
    static_risk: item.json.staticFlags?.staticRisk || 'unknown',
    risk_score: item.json.staticFlags?.riskScore || 0,
    llm_classification: llmClassification,
    final_decision: item.json.decision || 'unknown',
    was_sanitized: item.json.was_sanitized || false,
    was_blocked: item.json.is_blocked || false,

    // Flags de segurança
    security_flags: {
      forbidden_phrase: item.json.staticFlags?.hasForbiddenPhrase || false,
      secret_detected: item.json.staticFlags?.hasSecret || false,
      pii_detected: (item.json.staticFlags?.hasCPF || item.json.staticFlags?.hasEmail) || false,
      suspicious_url: item.json.staticFlags?.hasSuspiciousUrl || false
    }
  };

  // Log para auditoria
  console.log('FIREWALL_AUDIT_V2:', JSON.stringify(logEntry));

  // Log resumido para monitoramento
  const summary = `${logEntry.channel}|${logEntry.final_decision}|${logEntry.static_risk}|${logEntry.was_blocked}|${logEntry.processing_time_ms}ms`;
  console.log('FIREWALL_MONITOR_V2:', summary);

  // Alertas de segurança
  if (logEntry.static_risk === 'high' || logEntry.was_blocked || 
      (llmClassification && llmClassification.confianca > 0.8 && 
       ['override', 'exfiltracao', 'ilegal'].includes(llmClassification.classe))) {
    console.log('SECURITY_ALERT_V2:', JSON.stringify({
      timestamp: logEntry.timestamp,
      alert_type: 'high_risk_interaction',
      risk_level: logEntry.static_risk,
      classification: llmClassification?.classe,
      confidence: llmClassification?.confianca,
      blocked: logEntry.was_blocked,
      channel: logEntry.channel
    }));
  }

  items.push({
    json: {
      ...item.json,
      audit_log: logEntry
    }
  });
}

return items;
